import test from 'node:test';
import assert from 'node:assert/strict';
import {emptyWorkspace,normalizeWorkspace,WORKSPACE_KEY} from '../src/workspace-backup.js';
import {encodeEnvelope,decodeEnvelope,prepareLegacyMigration,prepareMigrationFromStorage,rollbackEnvelope,EXPANSION_KEY} from '../src/foundation/workspace-envelope.js';
import {entityRef,referenceKey,indexEntities,resolveEntity} from '../src/foundation/entity-refs.js';
import {evaluateCapability,LOCAL_CAPABILITIES} from '../src/foundation/capability-policy.js';
const legacy={done:['prompt'],projects:[{id:'p',method:'ads',title:'Muestra ficticia',done:[0]}],records:[{id:'r',title:'Registro ficticio',income:300,cost:20,views:0}],opportunities:[{id:'o',title:'Oferta ficticia',method:'ads',stage:'agreed',notes:'',quote:30000,cost:2000,minutes:60,project:'p',receivable:'c'}],cash:{opening:10000,period:'2026-11',essential:[],receivables:[{id:'c',title:'Oferta ficticia',total:30000,received:10000}]}};
test('foundation legacy migration retains projects, opportunities and cash links',()=>{const raw=JSON.stringify(legacy);const plan=prepareLegacyMigration(raw);assert.equal(plan.originalRaw,raw);assert.equal(plan.normalizationChanged,true);assert.deepEqual(decodeEnvelope(plan.envelope),normalizeWorkspace(legacy));assert.deepEqual(JSON.parse(plan.rollback),normalizeWorkspace(legacy))});
test('canonical envelope roundtrip and rollback preserve normalized state',()=>{const workspace=normalizeWorkspace(legacy);const plan=prepareLegacyMigration(JSON.stringify(workspace));assert.equal(plan.normalizationChanged,false);assert.deepEqual(decodeEnvelope(encodeEnvelope(workspace)),workspace);assert.deepEqual(JSON.parse(rollbackEnvelope(plan.envelope)),workspace)});
test('migration is read-only and uses separate storage key',()=>{const raw=JSON.stringify(legacy);let reads=0;const storage={getItem(k){reads++;assert.equal(k,WORKSPACE_KEY);return raw},setItem(){assert.fail('Must not write')},removeItem(){assert.fail('Must not delete')}};assert.equal(prepareMigrationFromStorage(storage).originalRaw,raw);assert.equal(reads,1);assert.notEqual(EXPANSION_KEY,WORKSPACE_KEY);assert.throws(()=>prepareMigrationFromStorage({getItem:()=>null}))});
test('invalid or future envelope rejects instead of overwriting data',()=>{const value=JSON.parse(encodeEnvelope(emptyWorkspace()));assert.throws(()=>decodeEnvelope(JSON.stringify({...value,version:2})));assert.throws(()=>decodeEnvelope(JSON.stringify({...value,extra:true})));assert.throws(()=>decodeEnvelope(JSON.stringify({...value,workspace:{...value.workspace,extra:true}})));assert.throws(()=>decodeEnvelope('{'));assert.throws(()=>prepareLegacyMigration('not-json'))});
test('noncanonical envelope rejects dropped or duplicate fields',()=>{const value=JSON.parse(encodeEnvelope(emptyWorkspace()));value.workspace.done=['prompt','prompt'];assert.throws(()=>decodeEnvelope(JSON.stringify(value)));const raw=JSON.stringify({...legacy,projects:[legacy.projects[0],legacy.projects[0]]});assert.throws(()=>prepareLegacyMigration(raw))});
test('migration reports unknown legacy data and retains original',()=>{const raw=JSON.stringify({...legacy,futureFeature:{data:1}});const plan=prepareLegacyMigration(raw);assert.equal(plan.normalizationChanged,true);assert.equal(JSON.parse(plan.originalRaw).futureFeature.data,1);assert.equal(Object.hasOwn(decodeEnvelope(plan.envelope),'futureFeature'),false)});
test('typed references distinguish namespaces and preserve exact IDs',()=>{const p=entityRef('project','same');const o=entityRef('opportunity','same');assert.notEqual(referenceKey(p),referenceKey(o));const i=indexEntities([{ref:p,value:{title:'P'}},{ref:o,value:{title:'O'}}]);assert.equal(resolveEntity(i,p).title,'P');assert.equal(resolveEntity(i,o).title,'O');assert.throws(()=>resolveEntity(i,entityRef('resource','same')));assert.throws(()=>indexEntities([{ref:p,value:1},{ref:p,value:2}]))});
test('typed reference rejects invalid kind, blank and oversized id',()=>{for(const [kind,id] of [['unknown','a'],['project',' '],['project','x'.repeat(101)],['project','a\n']])assert.throws(()=>entityRef(kind,id));assert.throws(()=>referenceKey({kind:'project',id:'x',extra:1}))});
const safe={capability:'workspace.plan',dataClass:'synthetic',network:false,costCentavos:0,operation:'local'};
test('local zero-cost preflight allows only explicit known capabilities',()=>{for(const capability of LOCAL_CAPABILITIES)assert.equal(evaluateCapability({...safe,capability}).allowed,true);assert.equal(evaluateCapability({...safe,dataClass:'personal'}).allowed,true)});
test('policy denies external, unknown cost, secret and unknown operations',()=>{for(const patch of [{network:true},{network:undefined},{operation:'external'},{costCentavos:1},{costCentavos:null},{costCentavos:undefined},{costCentavos:NaN},{dataClass:'secret'},{dataClass:'unknown'},{capability:'publish'},{capability:'ai.generate'}])assert.equal(evaluateCapability({...safe,...patch}).allowed,false,JSON.stringify(patch));assert.equal(evaluateCapability(null).allowed,false)});
